    VerseArtwork("comfort-psalms-34-22", "psalms-34-22", "The LORD redeems the soul", "Psalms 34:22", "The LORD redeems the soul of his servants. None of those who take refuge in him shall be condemned.", "comfort"),
    VerseArtwork("comfort-john-15-9", "john-15-9", "Remain in my love", "John 15:9", "Even as the Father has loved me, I also have loved you. Remain in my love.", "comfort"),
    VerseArtwork("comfort-isaiah-43-1", "isaiah-43-1", "I have called you by your name", "Isaiah 43:1", "But now the LORD who created you, Jacob, and he who formed you, Israel, says: “Don’t be afraid, for I have redeemed you. I have called you by your name. You are mine.", "comfort"),
    VerseArtwork("gratitude-1-chronicles-16-34", "1-chronicles-16-34", "Give thanks to the LORD", "1 Chronicles 16:34", "Oh give thanks to the LORD, for he is good, for his loving kindness endures forever.", "gratitude"),
    VerseArtwork("gratitude-exodus-15-2", "exodus-15-2", "I will praise him", "Exodus 15:2", "The LORD is my strength and song. He has become my salvation. This is my God, and I will praise him; my father’s God, and I will exalt him.", "gratitude"),
    VerseArtwork("gratitude-colossians-3-16", "colossians-3-16", "Singing with grace in your heart", "Colossians 3:16", "Let the word of Christ dwell in you richly; in all wisdom teaching and admonishing one another with psalms, hymns, and spiritual songs, singing with grace in your heart to the Lord.", "gratitude"),
    VerseArtwork("gratitude-psalm-34-8", "psalm-34-8", "Taste and see that the LORD is good", "Psalm 34:8", "Oh taste and see that the LORD is good. Blessed is the man who takes refuge in him.", "gratitude"),
    VerseArtwork("gratitude-psalm-84-11", "psalm-84-11", "He withholds no good thing", "Psalm 84:11", "For the LORD God is a sun and a shield. The LORD will give grace and glory. He withholds no good thing from those who walk blamelessly.", "gratitude"),
    VerseArtwork("gratitude-psalm-86-5", "psalm-86-5", "Abundant in loving kindness", "Psalm 86:5", "For you, Lord, are good, and ready to forgive, abundant in loving kindness to all those who call on you.", "gratitude"),
    VerseArtwork("gratitude-psalm-103-8", "psalm-103-8", "Merciful and gracious", "Psalm 103:8", "The LORD is merciful and gracious, slow to anger, and abundant in loving kindness.", "gratitude"),
    VerseArtwork("gratitude-isaiah-25-1", "isaiah-25-1", "You have done wonderful things", "Isaiah 25:1", "The LORD, you are my God. I will exalt you! I will praise your name, for you have done wonderful things, things planned long ago, in complete faithfulness and truth.", "gratitude"),
    VerseArtwork("gratitude-james-1-17", "james-1-17", "Every good gift and every perfect gift", "James 1:17", "Every good gift and every perfect gift is from above, coming down from the Father of lights, with whom can be no variation nor turning shadow.", "gratitude"),
    VerseArtwork("gratitude-psalms-115-1", "psalms-115-1", "To your name give glory", "Psalms 115:1", "Not to us, LORD, not to us, but to your name give glory, for your loving kindness, and for your truth’s sake.", "gratitude"),
    VerseArtwork("gratitude-psalms-115-12", "psalms-115-12", "The LORD remembers us", "Psalms 115:12", "The LORD remembers us. He will bless us. He will bless the house of Israel. He will bless the house of Aaron.", "gratitude"),
    VerseArtwork("gratitude-psalms-18-3", "psalms-18-3", "Worthy to be praised", "Psalms 18:3", "I call on the LORD, who is worthy to be praised; and I am saved from my enemies.", "gratitude"),
    VerseArtwork("gratitude-psalms-111-1", "psalms-111-1", "With my whole heart", "Psalms 111:1", "Praise the LORD! I will give thanks to the LORD with my whole heart, in the council of the upright, and in the congregation.", "gratitude"),
    VerseArtwork("gratitude-psalms-28-7", "psalms-28-7", "With my song I will thank him", "Psalms 28:7", "The LORD is my strength and my shield. My heart has trusted in him, and I am helped. Therefore my heart greatly rejoices. With my song I will thank him.", "gratitude"),
    VerseArtwork("gratitude-psalms-104-1", "psalms-104-1", "You are very great", "Psalms 104:1", "Bless the LORD, my soul. The LORD, my God, you are very great. You are clothed with honor and majesty.", "gratitude"),
    VerseArtwork("gratitude-1-corinthians-15-57", "1-corinthians-15-57", "Thanks be to God", "1 Corinthians 15:57", "But thanks be to God, who gives us the victory through our Lord Jesus Christ.", "gratitude"),
    VerseArtwork("gratitude-psalms-21-13", "psalms-21-13", "Sing and praise your power", "Psalms 21:13", "Be exalted, LORD, in your strength, so we will sing and praise your power.", "gratitude"),
    VerseArtwork("gratitude-psalms-31-21", "psalms-31-21", "Marvelous loving kindness", "Psalms 31:21", "Praise be to the LORD, for he has shown me his marvelous loving kindness in a strong city.", "gratitude"),
    VerseArtwork("gratitude-psalms-36-5", "psalms-36-5", "Your faithfulness reaches to the skies", "Psalms 36:5", "Your loving kindness, LORD, is in the heavens. Your faithfulness reaches to the skies.", "gratitude"),
    VerseArtwork("gratitude-psalms-106-1", "psalms-106-1", "Give thanks to the LORD", "Psalms 106:1", "Praise the LORD! Give thanks to the LORD, for he is good, for his loving kindness endures forever.", "gratitude"),
    VerseArtwork("gratitude-psalms-107-15", "psalms-107-15", "His wonderful deeds", "Psalms 107:15", "Let them praise the LORD for his loving kindness, for his wonderful deeds to the children of men!", "gratitude"),
    VerseArtwork("gratitude-psalms-111-4", "psalms-111-4", "His wonderful works", "Psalms 111:4", "He has caused his wonderful works to be remembered. The LORD is gracious and merciful.", "gratitude"),
    VerseArtwork("gratitude-psalms-116-5", "psalms-116-5", "Our God is merciful", "Psalms 116:5", "The LORD is gracious and righteous. Yes, our God is merciful.", "gratitude"),
    VerseArtwork("gratitude-psalms-117-2", "psalms-117-2", "Faithfulness endures forever", "Psalms 117:2", "For his loving kindness is great toward us. The LORD’s faithfulness endures forever. Praise the LORD!", "gratitude"),
    VerseArtwork("gratitude-psalms-118-4", "psalms-118-4", "His loving kindness endures forever", "Psalms 118:4", "Now let those who fear the LORD say that his loving kindness endures forever.", "gratitude"),
    VerseArtwork("gratitude-psalms-89-5", "psalms-89-5", "The heavens will praise your wonders", "Psalms 89:5", "The heavens will praise your wonders, LORD, your faithfulness also in the assembly of the holy ones.", "gratitude"),
    VerseArtwork("gratitude-psalms-116-17", "psalms-116-17", "The sacrifice of thanksgiving", "Psalms 116:17", "I will offer to you the sacrifice of thanksgiving, and will call on the LORD’s name.", "gratitude"),
    VerseArtwork("gratitude-psalms-104-24", "psalms-104-24", "The earth is full of your riches", "Psalms 104:24", "LORD, how many are your works! In wisdom, you have made them all. The earth is full of your riches.", "gratitude"),
    VerseArtwork("gratitude-psalms-104-33", "psalms-104-33", "I will sing to the LORD as long as I live", "Psalms 104:33", "I will sing to the LORD as long as I live. I will sing praise to my God while I have any being.", "gratitude"),
)
